//! Bit-exact parity with Pillow, driven by committed golden vectors.
//!
//! `tests/fixtures/pillow_golden/pillow_golden.jsonl` is generated by
//! `scripts/golden/gen_pillow_golden.py` from Pillow + numpy (the oracle;
//! development-time only). Every case is replayed here and compared
//! sample for sample: a mismatch is an implementation bug, never a reason
//! to edit the vector.
//!
//! Covered: `Image.resize` for L / LA / RGB / RGBA (premultiplied alpha),
//! `I;16` and `F` rasters, `reducing_gap` (including on `F` and `LA`),
//! `Image.reduce`, exact-ratio `Box`, same-size identity, single-row and
//! single-column shapes, exhaustive premultiply for `LA` and `RGBA`, and
//! the `convert` paths exposed by the kit.
//!
//! # Tolerances
//!
//! The contract allows a per-pixel absolute difference of 1 for 8-bit
//! rasters and a documented tolerance for 16-bit and float. What is
//! **measured** on the committed corpus is 0 samples for every mode: the
//! 8-bit path is Pillow's fixed point reproduced exactly, `I;16` rounds
//! and clamps after each pass as Pillow does, and `F` mirrors
//! `Reduce.c`'s `float`-grouped sub-sums and `Resampler.c`'s `f64`
//! accumulation. The constants below are therefore 0 and every test
//! asserts them; they exist so a regression names the measured delta
//! instead of "different", and so relaxing one is a visible edit of this
//! table.
//!
//! | mode | unit | allowed | measured | asserted |
//! |---|---|---|---|---|
//! | `L`, `LA`, `RGB`, `RGBA`, `CMYK` | 1 byte | ≤ 1 | 0 | 0 |
//! | `I;16` | 1 `u16` sample | documented | 0 | 0 |
//! | `F` | 1 `f32` sample | documented | 0 | 0 |

use sillstone_image::raster::{
    Cmyk, Gray, Image, La, Layout, ResamplingFilter, Rgb, Rgba, cmyk_to_rgb, reduce,
    resize_f32_with_gap, resize_with_gap, rgb_plane_to_l, rgb_to_cmyk, rgb_to_l,
};

const GOLDEN: &str = include_str!("fixtures/pillow_golden/pillow_golden.jsonl");

/// Maximum absolute sample difference asserted per mode: 0, the value
/// measured on the committed corpus (see the module table). The 8-bit
/// contract allows 1; this suite holds the tighter number.
const TOL_U8: f64 = 0.0;
const TOL_U16: f64 = 0.0;
const TOL_F32: f64 = 0.0;

/// One golden case; every field is a string, a number or null.
struct Case {
    id: String,
    op: String,
    mode: String,
    w: u32,
    h: u32,
    ow: u32,
    oh: u32,
    filter: Option<String>,
    gap: Option<f64>,
    to: Option<String>,
    input: Vec<u8>,
    expected: Vec<u8>,
}

/// Minimal parser for one flat JSON object (string / number / null values,
/// no escapes beyond `\"` and `\\`): enough for the generator's output,
/// without a JSON dependency.
fn parse_object(line: &str) -> Vec<(String, String)> {
    let b = line.as_bytes();
    let mut i = 0;
    let mut out = Vec::new();
    let skip_ws = |i: &mut usize| {
        while *i < b.len() && (b[*i] == b' ' || b[*i] == b',') {
            *i += 1;
        }
    };
    let string = |i: &mut usize| -> String {
        assert_eq!(b[*i], b'"');
        *i += 1;
        let mut s = String::new();
        while b[*i] != b'"' {
            if b[*i] == b'\\' {
                *i += 1;
            }
            s.push(b[*i] as char);
            *i += 1;
        }
        *i += 1;
        s
    };
    assert_eq!(b[i], b'{');
    i += 1;
    loop {
        skip_ws(&mut i);
        if b[i] == b'}' {
            break;
        }
        let key = string(&mut i);
        assert_eq!(b[i], b':');
        i += 1;
        let val = if b[i] == b'"' {
            string(&mut i)
        } else {
            let start = i;
            while b[i] != b',' && b[i] != b'}' {
                i += 1;
            }
            line[start..i].to_string()
        };
        out.push((key, val));
    }
    out
}

fn unhex(s: &str) -> Vec<u8> {
    assert_eq!(s.len() % 2, 0);
    (0..s.len() / 2)
        .map(|i| u8::from_str_radix(&s[2 * i..2 * i + 2], 16).expect("hex"))
        .collect()
}

fn cases() -> Vec<Case> {
    let mut lines = GOLDEN.lines();
    let meta = lines.next().expect("provenance line");
    assert!(meta.contains("\"_provenance\""), "first line is provenance");
    lines
        .filter(|l| !l.is_empty())
        .map(|l| {
            let kv = parse_object(l);
            let get = |k: &str| -> &str { &kv.iter().find(|(key, _)| key == k).expect("key").1 };
            let opt = |k: &str| -> Option<String> {
                let v = get(k);
                (v != "null").then(|| v.to_string())
            };
            let num = |k: &str| get(k).parse::<u32>().unwrap_or(0);
            Case {
                id: get("id").to_string(),
                op: get("op").to_string(),
                mode: get("mode").to_string(),
                w: num("w"),
                h: num("h"),
                ow: num("ow"),
                oh: num("oh"),
                filter: opt("filter"),
                gap: opt("gap").map(|g| g.parse().expect("gap")),
                to: opt("to"),
                input: unhex(get("input")),
                expected: unhex(get("expected")),
            }
        })
        .collect()
}

fn filter_of(name: &str) -> ResamplingFilter {
    match name {
        "nearest" => ResamplingFilter::Nearest,
        "box" => ResamplingFilter::Box,
        "bilinear" => ResamplingFilter::Bilinear,
        "bicubic" => ResamplingFilter::Bicubic,
        "lanczos" => ResamplingFilter::Lanczos,
        other => panic!("unknown filter {other}"),
    }
}

fn u16s(bytes: &[u8]) -> Vec<u16> {
    bytes
        .chunks_exact(2)
        .map(|c| u16::from_le_bytes([c[0], c[1]]))
        .collect()
}

fn f32s(bytes: &[u8]) -> Vec<f32> {
    bytes
        .chunks_exact(4)
        .map(|c| f32::from_le_bytes([c[0], c[1], c[2], c[3]]))
        .collect()
}

/// Decodes a produced or expected buffer into comparable samples.
///
/// `unit` is the sample width in bytes: 1 (`u8`), 2 (`u16`) or 4 (`f32`,
/// widened exactly into `f64`). Comparing in `f64` keeps the tolerance a
/// single number per mode without losing any 8-, 16- or 32-bit value.
fn samples(bytes: &[u8], unit: usize) -> Vec<f64> {
    match unit {
        1 => bytes.iter().map(|&b| f64::from(b)).collect(),
        2 => u16s(bytes).into_iter().map(f64::from).collect(),
        4 => f32s(bytes).into_iter().map(f64::from).collect(),
        other => panic!("unsupported sample width {other}"),
    }
}

/// Outcome of replaying a slice of the corpus.
struct Report {
    seen: usize,
    worst: f64,
    worst_id: String,
    fails: Vec<String>,
}

impl Report {
    fn assert_within(&self, tol: f64, what: &str) {
        assert!(
            self.fails.is_empty(),
            "{} of {} {what} cases exceed the tolerance of {tol}\n{}",
            self.fails.len(),
            self.seen,
            self.fails.join("\n")
        );
        assert!(
            self.worst <= tol,
            "{what}: worst measured delta {} in {} exceeds {tol}",
            self.worst,
            self.worst_id
        );
    }
}

/// Replays `ops` with `run` (which returns the produced buffer) and
/// measures the maximum absolute sample difference against `expected`.
fn check(ops: &[&str], unit: usize, tol: f64, run: impl Fn(&Case) -> Option<Vec<u8>>) -> Report {
    let mut report = Report {
        seen: 0,
        worst: 0.0,
        worst_id: String::new(),
        fails: Vec::new(),
    };
    for case in cases().iter().filter(|c| ops.contains(&c.op.as_str())) {
        let Some(got) = run(case) else { continue };
        report.seen += 1;
        let (got, want) = (samples(&got, unit), samples(&case.expected, unit));
        assert_eq!(
            got.len(),
            want.len(),
            "{}: sample count {} != expected {}",
            case.id,
            got.len(),
            want.len()
        );
        let mut worst = 0.0f64;
        let mut first = None;
        for (i, (a, b)) in got.iter().zip(&want).enumerate() {
            let d = (a - b).abs();
            if d > 0.0 && first.is_none() {
                first = Some(i);
            }
            if d > worst {
                worst = d;
            }
        }
        if worst > report.worst {
            report.worst = worst;
            report.worst_id = case.id.clone();
        }
        if worst > tol {
            report.fails.push(format!(
                "{}: max |delta| {worst} (first at sample {})",
                case.id,
                first.unwrap_or(0)
            ));
        }
    }
    report
}

fn run_resize<L: Layout>(case: &Case) -> Vec<u8> {
    let img = Image::<L, u8>::from_vec(case.w, case.h, case.input.clone()).expect("image");
    let filter = filter_of(case.filter.as_deref().expect("filter"));
    resize_with_gap(&img, case.ow, case.oh, filter, case.gap)
        .expect("resize")
        .as_slice()
        .to_vec()
}

fn run_reduce<L: Layout>(case: &Case) -> Vec<u8> {
    let img = Image::<L, u8>::from_vec(case.w, case.h, case.input.clone()).expect("image");
    reduce(&img, case.ow, case.oh)
        .expect("reduce")
        .as_slice()
        .to_vec()
}

#[test]
fn resize_8bit_modes_match_pillow() {
    let r = check(&["resize"], 1, TOL_U8, |c| match c.mode.as_str() {
        "L" => Some(run_resize::<Gray>(c)),
        "LA" => Some(run_resize::<La>(c)),
        "RGB" => Some(run_resize::<Rgb>(c)),
        "RGBA" => Some(run_resize::<Rgba>(c)),
        _ => None,
    });
    r.assert_within(TOL_U8, "8-bit resize");
    assert!(
        r.seen >= 250,
        "expected the 8-bit resize cases, saw {}",
        r.seen
    );
}

#[test]
fn resize_i16_matches_pillow() {
    let r = check(&["resize"], 2, TOL_U16, |c| {
        if c.mode != "I;16" {
            return None;
        }
        let img = Image::<Gray, u16>::from_vec(c.w, c.h, u16s(&c.input)).expect("image");
        let out = resize_with_gap(&img, c.ow, c.oh, filter_of(c.filter.as_deref()?), c.gap)
            .expect("resize");
        Some(
            out.as_slice()
                .iter()
                .flat_map(|v| v.to_le_bytes())
                .collect(),
        )
    });
    r.assert_within(TOL_U16, "I;16 resize");
    assert!(
        r.seen >= 24,
        "expected the I;16 resize cases, saw {}",
        r.seen
    );
}

#[test]
fn resize_f32_matches_pillow() {
    let r = check(&["resize"], 4, TOL_F32, |c| {
        if c.mode != "F" {
            return None;
        }
        let out = resize_f32_with_gap(
            &f32s(&c.input),
            c.w,
            c.h,
            1,
            c.ow,
            c.oh,
            filter_of(c.filter.as_deref()?),
            c.gap,
        )
        .expect("resize");
        Some(out.iter().flat_map(|v| v.to_le_bytes()).collect())
    });
    r.assert_within(TOL_F32, "F resize");
    assert!(r.seen >= 40, "expected the F resize cases, saw {}", r.seen);
}

#[test]
fn reduce_matches_pillow() {
    let r = check(&["reduce"], 1, TOL_U8, |c| match c.mode.as_str() {
        "L" => Some(run_reduce::<Gray>(c)),
        "LA" => Some(run_reduce::<La>(c)),
        "RGB" => Some(run_reduce::<Rgb>(c)),
        "RGBA" => Some(run_reduce::<Rgba>(c)),
        _ => None,
    });
    r.assert_within(TOL_U8, "reduce");
    assert!(r.seen >= 21, "expected the reduce cases, saw {}", r.seen);
}

/// Applies `f` to every `from`-channel pixel of `input`, concatenating the
/// `to`-channel results.
fn map_pixels(input: &[u8], from: usize, f: impl Fn(&[u8], &mut Vec<u8>)) -> Vec<u8> {
    let mut out = Vec::new();
    for px in input.chunks_exact(from) {
        f(px, &mut out);
    }
    out
}

#[test]
fn convert_matches_pillow() {
    let r = check(&["convert"], 1, TOL_U8, |c| {
        let to = c.to.as_deref()?;
        Some(match (c.mode.as_str(), to) {
            // Through the public `to_gray`, not a private helper: the
            // convert path is what the SDK exposes.
            ("RGB", "L") => {
                let img = Image::<Rgb, u8>::from_vec(c.w, c.h, c.input.clone()).expect("image");
                let gray = img.to_gray().as_slice().to_vec();
                let planar = rgb_plane_to_l(&c.input, 3, c.input.len() / 3);
                let scalar = map_pixels(&c.input, 3, |p, o| o.push(rgb_to_l(p[0], p[1], p[2])));
                assert_eq!(
                    gray, planar,
                    "{}: to_gray differs from the plane route",
                    c.id
                );
                assert_eq!(gray, scalar, "{}: SIMD route differs from scalar", c.id);
                gray
            }
            ("RGBA", "L") => {
                let img = Image::<Rgba, u8>::from_vec(c.w, c.h, c.input.clone()).expect("image");
                let gray = img.to_gray().as_slice().to_vec();
                let scalar = map_pixels(&c.input, 4, |p, o| o.push(rgb_to_l(p[0], p[1], p[2])));
                assert_eq!(gray, scalar, "{}: to_gray differs from rgb_to_l", c.id);
                gray
            }
            ("RGBA", "RGB") => {
                let img = Image::<Rgba, u8>::from_vec(c.w, c.h, c.input.clone()).expect("image");
                img.to_rgb().as_slice().to_vec()
            }
            ("RGB", "RGBA") => {
                let img = Image::<Rgb, u8>::from_vec(c.w, c.h, c.input.clone()).expect("image");
                img.to_rgba().as_slice().to_vec()
            }
            ("L", "RGB") => {
                let img = Image::<Gray, u8>::from_vec(c.w, c.h, c.input.clone()).expect("image");
                img.to_rgb().as_slice().to_vec()
            }
            ("L", "RGBA") => {
                let img = Image::<Gray, u8>::from_vec(c.w, c.h, c.input.clone()).expect("image");
                img.to_rgba().as_slice().to_vec()
            }
            ("RGB", "CMYK") => map_pixels(&c.input, 3, |p, o| {
                let (cy, m, y, k) = rgb_to_cmyk(p[0], p[1], p[2]);
                o.extend_from_slice(&[cy, m, y, k]);
            }),
            ("CMYK", "RGB") => {
                let img = Image::<Cmyk, u8>::from_vec(c.w, c.h, c.input.clone()).expect("image");
                let by_pixel = map_pixels(&c.input, 4, |p, o| {
                    let (r, g, b) = cmyk_to_rgb(p[0], p[1], p[2], p[3]);
                    o.extend_from_slice(&[r, g, b]);
                });
                assert_eq!(img.to_rgb().as_slice(), by_pixel.as_slice());
                by_pixel
            }
            other => panic!("unhandled conversion {other:?}"),
        })
    });
    r.assert_within(TOL_U8, "convert");
    assert!(r.seen >= 11, "expected the convert cases, saw {}", r.seen);
}

/// The whole corpus, one report: this is where the documented measured
/// deltas come from. `cargo test -- --nocapture` prints them.
#[test]
fn measured_max_deltas_are_zero() {
    let mut rows: Vec<(&str, f64, usize, f64)> = Vec::new();
    for (name, unit, tol, ops, runner) in [
        (
            "u8 resize/reduce",
            1usize,
            TOL_U8,
            vec!["resize", "reduce"],
            Box::new(|c: &Case| match (c.op.as_str(), c.mode.as_str()) {
                ("reduce", "L") => Some(run_reduce::<Gray>(c)),
                ("reduce", "LA") => Some(run_reduce::<La>(c)),
                ("reduce", "RGB") => Some(run_reduce::<Rgb>(c)),
                ("reduce", "RGBA") => Some(run_reduce::<Rgba>(c)),
                ("resize", "L") => Some(run_resize::<Gray>(c)),
                ("resize", "LA") => Some(run_resize::<La>(c)),
                ("resize", "RGB") => Some(run_resize::<Rgb>(c)),
                ("resize", "RGBA") => Some(run_resize::<Rgba>(c)),
                _ => None,
            }) as Box<dyn Fn(&Case) -> Option<Vec<u8>>>,
        ),
        (
            "I;16 resize",
            2,
            TOL_U16,
            vec!["resize"],
            Box::new(|c: &Case| {
                if c.mode != "I;16" {
                    return None;
                }
                let img = Image::<Gray, u16>::from_vec(c.w, c.h, u16s(&c.input)).expect("image");
                let out = resize_with_gap(&img, c.ow, c.oh, filter_of(&c.filter.clone()?), c.gap)
                    .expect("resize");
                Some(
                    out.as_slice()
                        .iter()
                        .flat_map(|v| v.to_le_bytes())
                        .collect(),
                )
            }),
        ),
        (
            "F resize",
            4,
            TOL_F32,
            vec!["resize"],
            Box::new(|c: &Case| {
                if c.mode != "F" {
                    return None;
                }
                let out = resize_f32_with_gap(
                    &f32s(&c.input),
                    c.w,
                    c.h,
                    1,
                    c.ow,
                    c.oh,
                    filter_of(&c.filter.clone()?),
                    c.gap,
                )
                .expect("resize");
                Some(out.iter().flat_map(|v| v.to_le_bytes()).collect())
            }),
        ),
    ] {
        let r = check(&ops, unit, tol, runner);
        println!("{name}: {} cases, max |delta| = {}", r.seen, r.worst);
        rows.push((name, r.worst, r.seen, tol));
    }
    for (name, worst, seen, tol) in rows {
        assert_eq!(
            worst, 0.0,
            "{name}: measured delta {worst} over {seen} cases"
        );
        assert!(seen > 0, "{name}: no cases replayed");
        assert!(worst <= tol, "{name}: {worst} > {tol}");
    }
}
